/**
 * GET FUNDED / CAPITAL DISPATCH
 * Read-only, fixture-backed applicant workspace prototype.
 * No operational network calls, no auth, no persistent browser storage.
 */
const root = document.getElementById('app');
const toastZone = document.getElementById('toast-zone');
const dialog = document.getElementById('app-dialog');
const applyUrl = 'https://get-funded-six.vercel.app/apply/';
const helpEmail = 'admin@distilledfunding.com';
const DOC_MAX_BYTES = 10 * 1024 * 1024;
const DOC_ALLOWED = new Set(['pdf', 'png', 'jpg', 'jpeg']);
const DOC_CATEGORIES = ['Bank Statements','Financial Statements','Tax Documents','Business Documents','Agreements','Other'];
const STATUS_FILTERS = ['All','Needs Action','In Progress','Completed','Closed'];
const NAV = [
  ['overview','Overview','grid'], ['applications','My applications','files'], ['documents','Documents','folder'],
  ['messages','Messages','message'], ['history','Funding history','archive'], ['settings','Account & settings','user'], ['support','Resources & support','help']
];
const paths = {
  grid:'<rect x="3" y="3" width="7" height="7"/><rect x="14" y="3" width="7" height="7"/><rect x="3" y="14" width="7" height="7"/><rect x="14" y="14" width="7" height="7"/>',
  files:'<rect x="4" y="3" width="16" height="18" rx="1"/><path d="M8 8h8M8 12h8M8 16h5"/>',
  folder:'<path d="M3 6a2 2 0 0 1 2-2h5l2 3h7a2 2 0 0 1 2 2v10H3z"/>',
  message:'<path d="M20 11a8 8 0 0 1-8 8 9 9 0 0 1-4-.9L3 20l1.8-5A8 8 0 1 1 20 11z"/>',
  archive:'<rect x="3" y="4" width="18" height="5" rx="1"/><path d="M5 9v11h14V9M10 13h4"/>',
  user:'<circle cx="12" cy="8" r="4"/><path d="M4 21c0-5 3.5-8 8-8s8 3 8 8"/>',
  help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 0 1 6 0c0 2-3 2-3 5m0 3v.4"/>',
  bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',
  arrow:'<path d="M5 12h14M13 6l6 6-6 6"/>',
  chevron:'<path d="m9 18 6-6-6-6"/>',
  check:'<path d="m4 12 5 5L20 6"/>',
  upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 17v3h16v-3"/>',
  close:'<path d="M5 5l14 14M19 5 5 19"/>',
  menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',
  search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',
  clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v6l4 2"/>',
  external:'<path d="M13 4h7v7M20 4l-9 9M19 14v6H4V5h6"/>',
  refresh:'<path d="M20 9a8 8 0 0 0-13-4L4 8M4 4v4h4M4 15a8 8 0 0 0 13 4l3-3m0 4v-4h-4"/>',
  info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7v.5"/>',
  file:'<path d="M6 2h8l5 5v15H6zM14 2v6h5M9 13h7M9 17h5"/>',
  filter:'<path d="M4 6h16M7 12h10M10 18h4"/>',
  send:'<path d="m22 2-7 20-4-9-9-4zM11 13 22 2"/>',
  shield:'<path d="M12 2 4 5v7c0 5 3 8 8 10 5-2 8-5 8-10V5zM9 12l2 2 4-4"/>',
  plus:'<path d="M12 5v14M5 12h14"/>',
  layers:'<path d="m12 2 9 5-9 5-9-5zM3 12l9 5 9-5M3 17l9 5 9-5"/>'
};
function icon(name,size=19){return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="square" stroke-linejoin="miter" aria-hidden="true">${paths[name]||paths.info}</svg>`;}
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = amount => new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(amount);
const date = str => str ? new Intl.DateTimeFormat('en-US',{month:'short',day:'2-digit',year:'numeric'}).format(new Date(`${str}T12:00:00`)) : '—';
const shortDate = str => str ? new Intl.DateTimeFormat('en-US',{month:'short',day:'2-digit'}).format(new Date(`${str}T12:00:00`)) : '—';
const bytes = v => v < 1048576 ? `${Math.ceil(v/1024)} KB` : `${(v/1048576).toFixed(1)} MB`;
const initials = name => name.split(' ').map(v=>v[0]).slice(0,2).join('').toUpperCase();
let fixture, statusMap, originalFixture;
let state = {
  applicationFilter:'All', applicationSort:'updated-desc', applicationSearch:'',
  documentApp:'all', documentCategory:'all', documentState:'all',
  messageApp:'all', messageSearch:'', activeThread:null, drafts:{}, simulatedReplies:{},
  selectedDocs:{}, fileErrors:{}, notificationOpen:false, mobileOpen:false,
  profile:null, profileDraft:null, unreadNotifications:new Set(), unreadThreads:new Set()
};
function bootState(){
  state.profile = structuredClone(fixture.applicant);
  state.profileDraft = structuredClone(fixture.applicant);
  state.unreadNotifications = new Set(fixture.notifications.filter(n=>n.unread).map(n=>n.id));
  state.unreadThreads = new Set(fixture.threads.filter(t=>t.unread).map(t=>t.id));
  state.activeThread = fixture.threads[0]?.id || null;
}
const appById = id => fixture.applications.find(a=>a.id===id);
const docsFor = id => fixture.documents.filter(d=>d.applicationId===id);
const eventsFor = id => fixture.events.filter(e=>e.applicationId===id);
const threadFor = id => fixture.threads.find(t=>t.applicationId===id);
const statusInfo = status => statusMap.statuses[status] || statusMap.unmappedFallback;
function statusBadge(status){const x=statusInfo(status);return `<span class="status status-${esc(x.tone)}"><span class="status-dot"></span>${esc(x.label)}</span>`;}
function docState(d){return state.selectedDocs[d.id] ? 'selected-in-demo' : d.state;}
function docBadge(d){ const s=docState(d);return `<span class="doc-status ${s}">${s==='requested' ? icon('clock',13) : icon('check',13)} ${esc(statusMap.documentStates[s]||s)}</span>`;}
function sectionTitle(number,title,right=''){return `<div class="section-title"><div class="section-title-left"><span class="index-no">${number}</span><h2>${title}</h2></div>${right}</div>`;}
function actionLink(href,label,variant='dark',extra=''){return `<a class="btn btn-${variant}" href="${esc(href)}" ${extra}>${label} ${icon('arrow',17)}</a>`;}
function empty(title,detail,link='#/overview',linkTitle='Back to overview'){return `<div class="empty-state"><div class="empty-graphic" aria-hidden="true"><span>—</span><span>∅</span><span>+</span></div><div class="mono subtle">NO MATCHING RECORDS / DEMO</div><h3>${esc(title)}</h3><p>${esc(detail)}</p>${actionLink(link,esc(linkTitle),'outline')}</div>`;}
function field(label,value){return `<div class="dossier-field"><span class="field-label">${esc(label)}</span><strong>${esc(value)}</strong></div>`;}
function eventsList(events,limited=false){let list=[...events].sort((a,b)=>b.date.localeCompare(a.date));if(limited)list=list.slice(0,4);return `<ol class="ledger-list">${list.map(e=>`<li><span class="ledger-icon">${icon(e.type==='document-request'?'folder':e.type==='completed'?'check':'clock',17)}</span><div><div class="ledger-head"><strong>${esc(e.title)}</strong><span class="mono dim">${date(e.date)}</span></div><p>${esc(e.body)}</p><a class="mini-link" href="#/applications/${encodeURIComponent(e.applicationId)}">${esc(e.applicationId)} ${icon('chevron',13)}</a></div></li>`).join('')}</ol>`;}
function timeline(app){return `<ol class="progress-rail">${app.progress.map((p,i)=>`<li class="rail-step rail-${esc(p.state)}"><span class="rail-marker">${p.state==='done'?icon('check',15):String(i+1).padStart(2,'0')}</span><details ${p.state==='current'?'open':''}><summary><span class="rail-label">${esc(p.label)}</span><span class="rail-date mono">${esc(p.date)}</span></summary><p>${esc(p.detail)}</p></details></li>`).join('')}</ol><div class="rail-legend"><span><i class="legend-done"></i>Recorded in demo</span><span><i class="legend-current"></i>Current sample step</span><span><i class="legend-future"></i>Possible future</span></div>`;}
function appSummary(app){return `<div class="application-summary"><div class="summary-head"><span class="mono">ACTIVE FILE / ${esc(app.id)}</span>${statusBadge(app.status)}</div><h3>${esc(app.business)}</h3><p>${esc(app.purpose)}</p><div class="summary-amount">${money(app.requestedAmount)}<span>Requested / sample</span></div><div class="summary-bottom"><div><small>Submitted</small><b>${date(app.submittedAt)}</b></div><div><small>Last update</small><b>${date(app.updatedAt)}</b></div></div><a class="text-arrow" href="#/applications/${esc(app.id)}">Open full dossier ${icon('arrow',18)}</a></div>`;}
function dispatch(app,compact=false){return `<section class="dispatch ${compact?'dispatch-compact':''}" aria-label="Action dispatch"><div class="dispatch-top"><span class="mono"><span class="blinker"></span> ACTION DISPATCH / ${esc(app.id)}</span><span class="mono dispatch-seq">PRIORITY 01 — DEMO</span></div><div class="dispatch-body"><div class="dispatch-copy"><div class="dispatch-eyebrow">NEXT REQUIRED MOVE</div><h2>${esc(app.actionTitle)}<span class="dispatch-star" aria-hidden="true">↗</span></h2><p>${esc(app.actionDescription)}</p><div class="dispatch-actions">${actionLink(app.actionRoute,'Handle demo action','dark')}<a class="plain-link" href="#/support">Need help? ${icon('arrow',16)}</a></div></div><div class="dispatch-meta"><span class="mono">FILE REFERENCE</span><strong>${esc(app.id)}</strong><div class="dispatch-meta-line"></div><span class="mono">CURRENT SIGNAL</span><b>${esc(statusInfo(app.status).label)}</b><span class="dispatch-watermark" aria-hidden="true">01/</span></div></div></section>`;}
function resourcesCards(){const items=[
  ['01','What Happens After Applying','Understand the difference between submitting information, document collection, review and a decision.'],
  ['02','Preparing Documents','See examples of common business documents and why accurate, readable copies matter.'],
  ['03','Understanding Offers','Learn what to compare in a real financing offer before deciding whether it fits.'],
  ['04','Common Funding Questions','Plain-language answers about status changes, supporting documents and updates.'],
  ['05','Protecting Your Information','Recognize legitimate requests and avoid sending sensitive data through unverified channels.']
];return `<div class="resource-grid">${items.map(([n,t,d])=>`<button type="button" class="resource-card" data-action="open-faq" data-faq="faq-${n}"><span class="resource-no mono">REF / ${n}</span><span class="resource-body"><strong class="resource-title">${t}</strong><span class="resource-desc">${d}</span></span><span class="resource-arrow">${icon('arrow',20)}</span></button>`).join('')}</div>`;}
function sidebar(active){return `<div class="sidebar-overlay ${state.mobileOpen?'is-open':''}" data-action="close-menu"></div><aside class="sidebar ${state.mobileOpen?'is-open':''}" aria-label="Primary navigation"><a class="brand" href="#/start" aria-label="Get Funded, demo access"><div class="brand-logomark">G<span>F</span><b>/</b></div><div><span class="brand-name">GET FUNDED<span class="brand-dot">.</span></span><span class="brand-description mono">CAPITAL DISPATCH</span></div></a><div class="sidebar-rule"></div><div class="sidebar-section-label mono">WORKSPACE / 001</div><nav class="side-nav" aria-label="Workspace sections">${NAV.map(([id,title,ico],i)=>`<a href="#/${id}" class="nav-item ${active===id?'active':''}" ${active===id?'aria-current="page"':''}><span class="nav-icon">${icon(ico,19)}</span><span>${title}</span>${id==='messages'&&state.unreadThreads.size?`<span class="nav-count">${state.unreadThreads.size}</span>`:''}<span class="nav-arrow">${icon('chevron',15)}</span></a>`).join('')}</nav><div class="sidebar-spacer"></div><div class="sidebar-help"><span class="mono">NEED A HUMAN?</span><strong>Questions about a request?</strong><a href="mailto:${helpEmail}" class="sidebar-help-link">Contact funding support ${icon('arrow',16)}</a></div><div class="sidebar-footer"><span>MOONSHINE CAPITAL</span><span class="mono">DEMO / 2026</span></div></aside>`;}
function topbar(active){const titles={overview:'Command overview',applications:'My applications',documents:'Document queue',messages:'Messages',history:'Funding history',settings:'Account & settings',support:'Help desk'};const unread=state.unreadNotifications.size;return `<header class="topbar"><div class="topbar-leading"><button class="icon-button mobile-menu" aria-label="Open navigation" data-action="open-menu" aria-expanded="${state.mobileOpen}">${icon('menu',22)}</button><div class="crumbs mono"><span>GET FUNDED</span><b>/</b><span>${esc(titles[active]||active)}</span></div></div><div class="topbar-actions"><span class="demo-pill"><span></span> DEMO · FICTIONAL DATA</span><div class="notifications-wrap"><button class="icon-button notify-button" data-action="toggle-notifications" aria-label="Notifications, ${unread} unread" aria-haspopup="true" aria-expanded="${state.notificationOpen}">${icon('bell',19)}${unread?`<em class="notification-count">${unread}</em>`:''}</button>${state.notificationOpen?notificationPanel():''}</div><a class="user-chip" href="#/settings" aria-label="Demo account settings"><span class="avatar">AM</span><span>ALEX M.</span></a></div></header>`;}
function notificationPanel(){return `<div class="notification-panel"><div class="notification-header"><div><span class="mono">DISPATCH ALERTS</span><h3>Notifications</h3></div><button class="icon-button small" data-action="toggle-notifications" aria-label="Close notifications">${icon('close',18)}</button></div><div class="notification-list">${fixture.notifications.map(n=>`<a href="${esc(n.href)}" data-notification="${esc(n.id)}" class="notification ${state.unreadNotifications.has(n.id)?'unread':''}"><span class="notification-dot"></span><span><b>${esc(n.title)}</b><small>${esc(n.body)}</small><span class="mono dim">${date(n.date)} / ${esc(n.applicationId)}</span></span>${icon('arrow',15)}</a>`).join('')}</div><button class="notification-clear" data-action="read-all">Mark all demo alerts as read</button></div>`;}
function footer(){return `<footer class="workspace-footer"><span class="mono">GET FUNDED / APPLICANT WORKSPACE</span><span>Prototype only · No data submitted · No authenticated access</span><a href="#/support">Help & resources ${icon('arrow',14)}</a></footer>`;}
function pageHead(kicker,title,subtitle,action=''){return `<div class="page-heading"><div><div class="page-kicker mono">${kicker}</div><h1>${title}</h1><p>${subtitle}</p></div>${action?`<div class="heading-action">${action}</div>`:''}</div>`;}
function startPage(){return `<div class="entry"><div class="entry-nav"><div class="entry-brand"><div class="entry-logomark">GF<span>///</span></div><span class="mono">MOONSHINE CAPITAL / DISTILLED FUNDING</span></div><span class="demo-pill"><span></span> DEMO · FICTIONAL DATA</span></div><div class="entry-grid"><div class="entry-intro"><div class="entry-eyebrow mono"><span class="entry-signal"></span> APPLICANT WORKSPACE / CONCEPT 001</div><h1>YOUR<br>FUNDING<br><em>WORKSPACE.</em></h1><p>Your capital. Your next move. Keep tabs on your funding request, see what's needed, and get straight to the right action.</p><div class="entry-cta">${actionLink('#/overview','Explore demo workspace','lime')}<span class="mono">NO SIGN-IN · SAMPLE RECORDS ONLY</span></div></div><div class="entry-visual"><div class="entry-visual-heading mono"><span>CAPITAL DISPATCH</span><span>LIVE UI / DEMO DATA</span></div><div class="entry-visual-plate"><div class="visual-alert"><span>01 / ACTION REQUIRED</span>${icon('arrow',27)}</div><div class="visual-core"><div class="visual-kicker mono">YOUR NEXT MOVE</div><strong>Keep your request moving.</strong><p>One clear action. One place for the details.</p><div class="visual-bars"><span></span><span></span><span></span><span></span></div></div><div class="visual-foot"><span class="mono">REQUEST STATUS / DEMO</span><b>CONTROL BEATS CONFUSION.</b></div></div><div class="entry-visual-bottom"><span>01 / STATUS</span><span>02 / DOCUMENTS</span><span>03 / SUPPORT</span></div></div></div><div class="entry-bottom"><span>FRONTEND CONCEPT — NOT A LIVE FUNDING PORTAL</span><button data-action="demo-access" class="entry-bottom-button">ABOUT THIS DEMO ${icon('arrow',16)}</button></div></div>`;}
function overviewPage(){const main=fixture.applications[0];const next=docsFor(main.id).filter(d=>docState(d)==='requested').length;return `${pageHead('COMMAND OVERVIEW / THURSDAY, 19 NOV 2026','Good to have you back, Alex.','One place to track your requests, handle the next step, and find support.')}<div class="overview-statusline"><span><b class="signal-square"></b> ${statusInfo(main.status).label.toUpperCase()} ON ${esc(main.id)}</span><span class="mono">${next} OPEN DOCUMENT REQUEST${next===1?'':'S'} · DEMO</span></div>${dispatch(main)}<div class="overview-grid"><section class="surface progress-panel">${sectionTitle('02','Application progress',`<a href="#/applications/${esc(main.id)}" class="mini-link">Full dossier ${icon('arrow',15)}</a>`)}<div class="panel-note">${esc(main.business)} <span class="mono">/ ${esc(main.id)}</span></div>${timeline(main)}</section><section class="surface summary-panel">${sectionTitle('03','Active request')}${appSummary(main)}</section></div><div class="overview-grid overview-lower"><section class="surface ledger-panel">${sectionTitle('04','Activity ledger',`<a class="mini-link" href="#/applications/${esc(main.id)}">All updates ${icon('arrow',15)}</a>`)}${eventsList(fixture.events.filter(e=>e.applicationId===main.id),true)}</section><section class="quick-panel"><div class="quick-intro"><span class="mono">05 / QUICK ACCESS</span><h2>Need something else?</h2></div><a href="#/documents" class="quick-link">${icon('folder',21)}<span><strong>Document queue</strong><small>Review sample requests</small></span>${icon('arrow',19)}</a><a href="#/applications" class="quick-link">${icon('files',21)}<span><strong>All applications</strong><small>Three fictional records</small></span>${icon('arrow',19)}</a><a href="#/support" class="quick-link">${icon('help',21)}<span><strong>Resources & support</strong><small>Get answers or contact us</small></span>${icon('arrow',19)}</a></section></div>`;}
function filteredApps(){let a=[...fixture.applications];if(state.applicationFilter!=='All')a=a.filter(v=>statusInfo(v.status).group===state.applicationFilter);
const q=state.applicationSearch.trim().toLowerCase();if(q)a=a.filter(v=>[v.id,v.business,v.purpose,v.nextAction,statusInfo(v.status).label].some(s=>s.toLowerCase().includes(q)));
return a.sort((a,b)=>{switch(state.applicationSort){case 'updated-asc':return a.updatedAt.localeCompare(b.updatedAt);case 'amount-desc':return b.requestedAmount-a.requestedAmount;case 'amount-asc':return a.requestedAmount-b.requestedAmount;case 'business-asc':return a.business.localeCompare(b.business);default:return b.updatedAt.localeCompare(a.updatedAt);}});}
function appListResults(){const apps=filteredApps();return `${apps.length?`<div class="desktop-table-wrap"><table class="data-table"><thead><tr><th>Reference / business</th><th>Funding purpose</th><th class="numeric">Requested</th><th>Submitted / updated</th><th>Status</th><th>Next action</th><th><span class="sr-only">Open</span></th></tr></thead><tbody>${apps.map(a=>`<tr><td><a class="table-business" href="#/applications/${esc(a.id)}">${esc(a.business)}</a><span class="mono muted table-ref">${esc(a.id)}</span></td><td>${esc(a.purpose)}</td><td class="numeric money-cell">${money(a.requestedAmount)}</td><td><span>${date(a.submittedAt)}</span><small>Updated ${date(a.updatedAt)}</small></td><td>${statusBadge(a.status)}</td><td class="next-cell">${esc(a.nextAction)}</td><td><a class="row-arrow" aria-label="View ${esc(a.id)}" href="#/applications/${esc(a.id)}">${icon('arrow',19)}</a></td></tr>`).join('')}</tbody></table></div><div class="app-mobile-list">${apps.map(a=>`<a class="app-mobile-card" href="#/applications/${esc(a.id)}"><div class="mobile-app-top"><span class="mono">${esc(a.id)}</span>${statusBadge(a.status)}</div><h3>${esc(a.business)}</h3><p>${esc(a.purpose)}</p><div class="mobile-app-middle"><strong>${money(a.requestedAmount)}</strong><small>Updated ${date(a.updatedAt)}</small></div><div class="mobile-app-foot"><span>${esc(a.nextAction)}</span>${icon('arrow',19)}</div></a>`).join('')}</div>`:empty('No applications found','Try another status filter or search term. All records here are fictional.','#/applications','Show all applications')}<div class="table-caption mono">SHOWING ${apps.length} OF ${fixture.applications.length} FICTIONAL REQUESTS</div>`;}
function applicationsPage(){return `${pageHead('APPLICATIONS / REQUEST REGISTER','Your applications.','A clear view of each request, its recorded state, and any next step.',actionLink(applyUrl,'Start another funding request','outline','target="_blank" rel="noopener noreferrer"'))}<div class="surface filter-surface"><div class="filter-toolbar"><div class="search-field">${icon('search',20)}<label class="sr-only" for="app-search">Search applications</label><input id="app-search" data-field="app-search" placeholder="Search business, request ID, purpose…" value="${esc(state.applicationSearch)}" autocomplete="off" type="search"></div><div class="sort-field"><span class="mono">SORT</span><label class="sr-only" for="app-sort">Sort applications</label><select id="app-sort" data-field="app-sort"><option value="updated-desc" ${state.applicationSort==='updated-desc'?'selected':''}>Recently updated</option><option value="updated-asc" ${state.applicationSort==='updated-asc'?'selected':''}>Oldest update</option><option value="amount-desc" ${state.applicationSort==='amount-desc'?'selected':''}>Amount: high to low</option><option value="amount-asc" ${state.applicationSort==='amount-asc'?'selected':''}>Amount: low to high</option><option value="business-asc" ${state.applicationSort==='business-asc'?'selected':''}>Business: A–Z</option></select></div></div><div class="filter-chips" aria-label="Filter applications by status">${STATUS_FILTERS.map(x=>`<button class="filter-chip ${state.applicationFilter===x?'selected':''}" data-filter-app="${x}" aria-pressed="${state.applicationFilter===x}">${x}</button>`).join('')}</div></div><section class="surface list-section">${sectionTitle('01','Request register')}<div id="application-results">${appListResults()}</div></section><p class="under-note">Request statuses shown here are deterministic demonstration data. Real decisions or underwriting activity cannot be inferred from an application submission.</p>`;}
function notFoundPage(id){return `${pageHead('ERROR / REQUEST NOT FOUND','We can’t find that record.','This fictional request ID does not exist in the demonstration data.')}${empty('Unknown application reference',`The demo has no record for ${id}.`,'#/applications','Return to applications')}`;}
function applicationDetailPage(id){const a=appById(id);if(!a)return notFoundPage(id);const related=docsFor(id);const t=threadFor(id);return `${pageHead('APPLICATION DOSSIER / '+esc(a.id),esc(a.business),esc(a.purpose),`<a class="btn btn-outline" href="#/applications">${icon('chevron',17)} All applications</a>`)}<div class="dossier-flag"><div class="mono">REQUEST / ${esc(a.id)}</div>${statusBadge(a.status)}<div class="mono">LAST UPDATED ${date(a.updatedAt).toUpperCase()} · DEMO</div></div><div class="dossier-grid"><section class="surface dossier-main">${sectionTitle('01','Application dossier')}<div class="dossier-amount"><span>AMOUNT REQUESTED / SAMPLE</span><strong>${money(a.requestedAmount)}</strong></div><div class="dossier-fields">${field('Business',a.business)}${field('Funding purpose',a.purpose)}${field('Submitted',date(a.submittedAt))}${field('Last update',date(a.updatedAt))}${field('Reference',a.id)}${field('Status',statusInfo(a.status).label)}</div><div class="dossier-action"><span class="mono">CURRENT GUIDANCE</span><h3>${esc(a.actionTitle)}</h3><p>${esc(a.actionDescription)}</p>${actionLink(a.actionRoute,esc(a.nextAction),'dark')}</div></section><section class="surface dossier-progress">${sectionTitle('02','Progress rail')}${timeline(a)}</section></div><div class="detail-grid"><section class="surface">${sectionTitle('03','Related document queue',`<a class="mini-link" href="#/documents?app=${esc(a.id)}">View queue ${icon('arrow',15)}</a>`)}<div class="related-docs">${related.length?related.map(d=>`<a href="#/documents?app=${esc(a.id)}" class="related-doc"><span class="doc-mini-icon">${icon('file',19)}</span><span><strong>${esc(d.title)}</strong><small>${esc(d.category)} · ${esc(d.id)}</small></span>${docBadge(d)}</a>`).join(''):empty('No related documents','No sample document requests were recorded for this application.')}</div></section><section class="surface">${sectionTitle('04','Applicant-visible messages',`<a class="mini-link" href="#/messages?app=${esc(a.id)}">Open thread ${icon('arrow',15)}</a>`)}${t?`<div class="message-snippet"><span class="mono">${esc(t.id)} / ${date(t.messages[0].date)}</span><h3>${esc(t.subject)}</h3><p>${esc(t.messages[0].body)}</p><a class="text-arrow" href="#/messages?app=${esc(a.id)}">Read & draft reply ${icon('arrow',17)}</a></div>`:empty('No messages','No conversations in this sample record.')}</section></div><section class="surface detail-ledger">${sectionTitle('05','Activity ledger')} ${eventsList(eventsFor(id))}</section><div class="detail-bottom"><div><span class="mono">NEED TO CORRECT AN APPLICATION DETAIL?</span><p>Contact support to request an update. The demo cannot change a submitted request.</p></div>${actionLink('#/support','Get support','outline')}</div>`;}
function filteredDocs(){return fixture.documents.filter(d=>(state.documentApp==='all'||d.applicationId===state.documentApp)&&(state.documentCategory==='all'||d.category===state.documentCategory)&&(state.documentState==='all'||docState(d)===state.documentState));}
function options(items,value){return items.map(([v,n])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(n)}</option>`).join('');}
function docRows(){const a=filteredDocs();return a.length?a.map((d,i)=>{const app=appById(d.applicationId),selected=state.selectedDocs[d.id],isRequested=d.state==='requested';return `<article class="document-item"><div class="doc-line-top"><span class="mono">${String(i+1).padStart(2,'0')} / ${esc(d.id)} · ${esc(d.category)}</span>${docBadge(d)}</div><div class="doc-content"><div><h3>${esc(d.title)}</h3><p>${esc(d.instructions)}</p><div class="doc-facts"><span>Requested <b>${date(d.requestedAt)}</b></span><span>File <a href="#/applications/${esc(d.applicationId)}">${esc(d.applicationId)}</a></span><span>Action <b>${esc(d.action)}</b></span></div></div>${isRequested?`<div class="doc-demo-area"><div class="file-dropzone ${selected?'has-selection':''}" data-drop-doc="${esc(d.id)}" tabindex="0" role="button" aria-label="Choose a demo file for ${esc(d.title)}" data-action="choose-file" data-doc="${esc(d.id)}">${icon(selected?'check':'upload',24)}<strong>${selected?'File selected for demonstration':'Choose or drop a file'}</strong><small>${selected?esc(selected.name)+' · '+bytes(selected.size):'PDF, JPG, PNG · 10 MB maximum'}</small><input class="file-input" type="file" data-file-input="${esc(d.id)}" accept=".pdf,.jpg,.jpeg,.png,application/pdf,image/jpeg,image/png" aria-label="Choose file for ${esc(d.title)}" tabindex="-1"></div>${selected?`<div class="doc-demo-note">Demo selection only — no file uploaded.<div class="selection-actions"><button class="mini-action" data-action="clear-file" data-doc="${esc(d.id)}">Cancel selection</button><button class="mini-action" data-action="choose-file" data-doc="${esc(d.id)}">Try another file</button></div></div>`:''}${state.fileErrors[d.id]?`<div class="field-error" role="alert">${esc(state.fileErrors[d.id])} <button class="mini-action" data-action="choose-file" data-doc="${esc(d.id)}">Retry</button></div>`:''}</div>`:`<div class="doc-file-state"><span>${icon('shield',20)}</span><strong>${esc(statusMap.documentStates[d.state])}</strong><small>Fictional fixture only</small></div>`}</div></article>`;}).join(''):empty('No matching document requests','Adjust the application, category or state filters to see other sample documents.','#/documents','Show document queue');}
function documentsPage(query){if(query?.has('app') && fixture.applications.some(a=>a.id===query.get('app')))state.documentApp=query.get('app');return `${pageHead('DOCUMENTS / INTAKE QUEUE','The document queue.','Review the sample requests and practice selecting documents. Nothing is transmitted.')}<div class="document-alert">${icon('info',23)}<div><strong>Demo selection only — no file uploaded.</strong><p>Files stay on your device. Only their name and size are shown temporarily in browser memory. No real document request can be fulfilled here.</p></div></div><div class="surface doc-filter-surface"><label>APPLICATION<select data-field="doc-app">${options([['all','All applications'],...fixture.applications.map(a=>[a.id,`${a.id} · ${a.business}`])],state.documentApp)}</select></label><label>CATEGORY<select data-field="doc-category">${options([['all','All categories'],...DOC_CATEGORIES.map(c=>[c,c])],state.documentCategory)}</select></label><label>STATE<select data-field="doc-state">${options([['all','All states'],['requested','Requested'],['selected-in-demo','Selected in Demo'],['received','Received · fictional'],['under-review','Under Review · fictional']],state.documentState)}</select></label><button class="btn btn-outline filter-reset" data-action="reset-doc-filters">Reset filters ${icon('refresh',15)}</button></div><section class="surface docs-queue">${sectionTitle('01','Requested items',`<span class="mono subtle">${filteredDocs().length} VISIBLE / ${fixture.documents.length} TOTAL</span>`)}<div class="document-list">${docRows()}</div></section><div class="resource-note">${icon('shield',20)}<p>Future real uploads will require authenticated access, verified application ownership and a secure document service. This demo provides none of those services.</p></div>`;}
function filteredThreads(){return fixture.threads.filter(t=>(state.messageApp==='all'||t.applicationId===state.messageApp)&&[t.subject,t.applicationId,appById(t.applicationId)?.business||'',...t.messages.map(m=>m.body)].some(x=>x.toLowerCase().includes(state.messageSearch.toLowerCase().trim())));}
function messageThreadList(){const list=filteredThreads();return list.length?list.map(t=>{const app=appById(t.applicationId);return `<button class="thread-item ${state.activeThread===t.id?'active':''}" data-action="thread" data-id="${esc(t.id)}"><span class="thread-bar"></span><span class="thread-content"><span class="thread-top"><span class="mono">${esc(t.applicationId)}</span>${state.unreadThreads.has(t.id)?'<i class="unread-signal" aria-label="Unread"></i>':''}</span><strong>${esc(t.subject)}</strong><span class="thread-company">${esc(app.business)}</span><small>${esc(t.messages[0]?.body||'')}</small></span>${icon('chevron',17)}</button>`;}).join(''):empty('No conversations found','Try a broader search or change the application filter.','#/messages','View all conversations');}
function activeThread(){return filteredThreads().find(t=>t.id===state.activeThread) || filteredThreads()[0];}
function threadContent(){const t=activeThread();if(!t)return empty('Choose a conversation','Select a message thread from the left column.');const msgs=[...t.messages,...(state.simulatedReplies[t.id]||[])].sort((a,b)=>a.date.localeCompare(b.date));return `<div class="message-detail-head"><div><span class="mono">${esc(t.applicationId)} / ${esc(t.id)}</span><h2>${esc(t.subject)}</h2><small>${esc(appById(t.applicationId)?.business)}</small></div><span class="status status-neutral"><span class="status-dot"></span> FICTIONAL THREAD</span></div><div class="message-conversation">${msgs.map(m=>`<div class="message-bubble ${m.direction==='out'?'out':''} ${m.unsent?'unsent':''}"><div class="message-bubble-head"><strong>${esc(m.from)}</strong><time>${m.unsent?'Not sent':date(m.date)}</time></div><p>${esc(m.body)}</p>${m.unsent?'<span class="demo-not-sent">Demo only — no message sent.</span>':''}</div>`).join('')}</div><div class="message-compose"><label for="reply-box">DRAFT A DEMO REPLY <span class="mono">/ NOT CONNECTED</span></label><textarea id="reply-box" data-field="message-draft" rows="4" maxlength="1200" placeholder="Type a sample response… nothing will be sent.">${esc(state.drafts[t.id]||'')}</textarea><div class="compose-footer"><p>Demo only — no message sent. Do not enter real personal or financial information.</p><button class="btn btn-dark" data-action="send-demo" ${!(state.drafts[t.id]||'').trim()?'disabled':''}>Simulate send ${icon('send',17)}</button></div></div>`;}
function messagesPage(query){if(query?.has('app') && appById(query.get('app'))){state.messageApp=query.get('app');const t=threadFor(state.messageApp);if(t)state.activeThread=t.id;}if(!filteredThreads().some(t=>t.id===state.activeThread))state.activeThread=filteredThreads()[0]?.id||null;return `${pageHead('MESSAGES / COMMUNICATIONS','Conversations, organized.','Read fictional messages by request and draft a sample reply. No message can be sent.')}<div class="messaging-layout"><section class="surface conversation-sidebar"><div class="conversation-toolbar"><label class="sr-only" for="message-filter">Filter conversations by application</label><select id="message-filter" data-field="message-app">${options([['all','All applications'],...fixture.applications.map(a=>[a.id,a.business])],state.messageApp)}</select><div class="search-field compact">${icon('search',17)}<label class="sr-only" for="message-search">Search conversations</label><input id="message-search" data-field="message-search" placeholder="Search conversations" value="${esc(state.messageSearch)}"></div></div><div id="thread-results" class="thread-list">${messageThreadList()}</div></section><section class="surface conversation-main" id="thread-content">${threadContent()}</section></div>`;}
function historyPage(){const history=fixture.history;return `${pageHead('FUNDING HISTORY / COMPLETED RECORDS','Past requests. Clear records.','A fictional example of a completed request. No balances, repayment terms, or statements are represented.',actionLink('#/applications','All applications','outline'))}<div class="history-intro"><span class="mono">SAMPLE ARCHIVE / 001</span><h2>Completed doesn't mean forgotten.</h2><p>Return to a previous request to see its sample timeline and activity history. Actual funding records would require verified source data.</p></div>${history.map(h=>{const a=appById(h.applicationId);return `<article class="surface completed-record"><div class="completed-mark">${icon('check',37)}<span class="mono">COMPLETED / DEMO</span></div><div class="completed-info"><span class="mono">${esc(h.label)} · ${esc(a.id)} · ${date(h.recordedAt)}</span><h3>${esc(a.business)}</h3><p>${esc(a.purpose)}</p><div class="completed-metrics"><div><small>Requested in sample</small><strong>${money(a.requestedAmount)}</strong></div><div><small>Completed record</small><strong>${date(h.recordedAt)}</strong></div></div><p class="completed-disclaimer">${esc(h.note)}</p></div><div class="completed-link">${actionLink(`#/applications/${a.id}`,'View record','outline')}</div></article>`;}).join('')}<section class="surface history-empty"><div class="mono">02 / ADDITIONAL HISTORY</div>${empty('No other completed sample records','Your other example requests are either in progress or require action. They will not appear as completed until their fixture status changes.','#/applications','View active requests')}</section>`;}
function settingsPage(){const p=state.profileDraft;return `${pageHead('ACCOUNT / PREFERENCES','Make this workspace yours.','Edit fictional details and communication preferences in browser memory only.')}<div class="settings-layout"><section class="surface settings-form">${sectionTitle('01','Demo profile')}<div class="profile-stripe"><span class="profile-avatar">${initials(p.firstName+' '+p.lastName)}</span><div><strong>${esc(p.firstName)} ${esc(p.lastName)}</strong><span class="mono">DEMO APPLICANT · NOT VERIFIED</span></div></div><form id="profile-form" class="profile-form"><div class="form-grid"><label>FIRST NAME<input name="firstName" required maxlength="60" value="${esc(p.firstName)}" autocomplete="off"></label><label>LAST NAME<input name="lastName" required maxlength="60" value="${esc(p.lastName)}" autocomplete="off"></label><label class="span-2">EMAIL (FICTIONAL)<input name="email" required type="email" maxlength="120" value="${esc(p.email)}" autocomplete="off"></label><label class="span-2">BUSINESS NAME<input name="business" maxlength="120" required value="${esc(p.business)}" autocomplete="off"></label><label class="span-2">LOCATION<input name="location" maxlength="120" value="${esc(p.location)}" autocomplete="off"></label></div><div class="settings-save"><p>Changes are not saved to any account or server.</p><button class="btn btn-dark" type="submit">Save demo changes ${icon('check',16)}</button></div></form></section><div class="settings-side"><section class="surface preferences-section">${sectionTitle('02','Communications')}<label class="toggle-row"><span><strong>Service notifications</strong><small>Example application and document messages. Preference only; no real messages.</small></span><input type="checkbox" data-pref="serviceEmailEnabled" ${p.serviceEmailEnabled?'checked':''}><span class="toggle-ui" aria-hidden="true"></span></label><label class="toggle-row"><span><strong>Marketing emails</strong><small>Separate optional opt-in. Disabled by default and never transmitted in this demo.</small></span><input type="checkbox" data-pref="marketingEmailEnabled" ${p.marketingEmailEnabled?'checked':''}><span class="toggle-ui" aria-hidden="true"></span></label></section><section class="surface security-section">${sectionTitle('03','Access & security')}<div class="security-icon">${icon('shield',30)}</div><h3>Future secure access</h3><p>This prototype has no authentication, active sessions, verified applicant identity or live account access. A real version must verify identity and enforce server-side application ownership before exposing records or documents.</p><span class="not-connected">${icon('info',15)} NOT CONNECTED IN DEMO</span></section><section class="reset-section"><span class="mono">DEMO CONTROLS</span><button data-action="reset-demo" class="btn btn-outline">Reset all demo changes ${icon('refresh',16)}</button><p>Resets fictional preferences, unsent replies, selected file metadata and notification read states.</p></section></div></div>`;}
function supportPage(){const faqs=[
['01','What Happens After Applying','Submission confirms a request was received by a system; it does not mean it is under review or approved. Real status should come from verified operational records.'],
['02','Preparing Documents','Documents often include business statements, financial statements, tax records and agreements. Only provide files through a verified, secure channel. This prototype does not accept uploads.'],
['03','Understanding Offers','Review the total cost, payment schedule, fees, term, collateral or guarantees, and early-payment conditions of any actual offer. This demonstration intentionally contains no loan terms.'],
['04','Common Funding Questions','Use the specific request reference when asking about your status. We cannot verify real application information through this fictional workspace.'],
['05','Protecting Your Information','Never email sensitive identity documents or complete banking credentials to an unverified recipient. Confirm the official submission channel before sharing personal information.']
];return `${pageHead('SUPPORT / FIELD MANUAL','Answers. Without the runaround.','Guidance for common next steps and a direct way to contact Moonshine Capital.')}<section>${sectionTitle('01','Resource library')}${resourcesCards()}</section><div class="support-grid"><section class="surface faq-section">${sectionTitle('02','Common questions')}<div class="faq-list">${faqs.map(([n,q,a])=>`<details id="faq-${n}"><summary><span class="mono">${n}</span><strong>${q}</strong>${icon('plus',19)}</summary><p>${a}</p></details>`).join('')}</div></section><aside class="contact-card"><span class="mono">03 / DIRECT SUPPORT</span><div class="contact-graphic" aria-hidden="true">?</div><h2>A question that needs a person?</h2><p>For a correction or update request, reference the correct application ID and describe what needs to change. Don't include sensitive files or complete bank details in an unverified email.</p><a href="mailto:${helpEmail}?subject=Funding%20request%20question" class="btn btn-lime">Email support ${icon('external',17)}</a><div class="support-email">${helpEmail}</div><div class="contact-foot">No live chat or response-time guarantee is provided.</div></aside></div>`;}
function routeData(){let raw=location.hash.slice(1)||'/start';const [path,search='']=raw.split('?');const bits=path.split('/').filter(Boolean);return {section:bits[0]||'start',detail:bits[1]||null,query:new URLSearchParams(search)};}
function render(){const {section,detail,query}=routeData();const pages={overview:overviewPage,applications:applicationsPage,documents:()=>documentsPage(query),messages:()=>messagesPage(query),history:historyPage,settings:settingsPage,support:supportPage};if(section==='start'){root.innerHTML=startPage();root.className='';document.title='Get Funded — Demo Access';return;}
let active=section==='applications'&&detail?'applications':section;const content=section==='applications'&&detail?applicationDetailPage(decodeURIComponent(detail)):pages[section]?.()||notFoundPage(section);
root.innerHTML=`<div class="workspace">${sidebar(active)}<div class="main-column">${topbar(active)}<main class="content" id="main-content">${content}</main>${footer()}</div></div>`;root.className='';document.title=`${active[0].toUpperCase()+active.slice(1)} | Get Funded — Demo`;}
function navigate(){state.mobileOpen=false;state.notificationOpen=false;render();window.scrollTo({top:0,behavior:'instant'});}
function notify(message,type='info'){toastZone.innerHTML=`<div class="toast toast-${type}" role="status">${icon(type==='error'?'info':'check',19)}<span>${esc(message)}</span><button data-action="dismiss-toast" aria-label="Dismiss notification">${icon('close',16)}</button></div>`;clearTimeout(notify.timeout);notify.timeout=setTimeout(()=>{toastZone.innerHTML='';},5500);}
function modal(title,body,confirmReset=false){document.querySelector('.dialog-footer').innerHTML=confirmReset?'<button class="btn btn-outline" value="close">Cancel</button><button type="button" class="btn btn-dark" data-action="confirm-reset">Reset demo</button>':'<button class="btn btn-dark" value="close">Close</button>';document.getElementById('dialog-body').innerHTML=`<div class="dialog-kicker mono">CAPITAL DISPATCH / DEMO NOTICE</div><h2 id="dialog-title">${esc(title)}</h2><p>${esc(body)}</p>`;if(!dialog.open)dialog.showModal();}
function selectMetadata(docId,file){const doc=fixture.documents.find(d=>d.id===docId);if(!doc||doc.state!=='requested')return;
  const ext=(file.name.split('.').pop()||'').toLowerCase();
  const validMime={pdf:'application/pdf',png:'image/png',jpg:'image/jpeg',jpeg:'image/jpeg'};
  let error = !DOC_ALLOWED.has(ext) ? 'Unsupported file type. Choose PDF, JPG, or PNG.' : file.type && file.type!==validMime[ext] ? 'File type does not match its extension.' : file.size > DOC_MAX_BYTES ? 'That file exceeds the 10 MB demo limit.' : file.size === 0 ? 'Empty files cannot be selected in this demo.' : '';
  if(error){delete state.selectedDocs[docId];state.fileErrors[docId]=error;render();notify(error,'error');return;}
  state.selectedDocs[docId]={name:file.name.slice(0,180),size:file.size,type:ext};delete state.fileErrors[docId];render();notify('Demo selection recorded in browser memory. No file uploaded.');}
function resetDocs(){state.documentApp='all';state.documentCategory='all';state.documentState='all';if(location.hash.includes('?'))history.replaceState(null,'',location.pathname+location.search+'#/documents');render();}
function updateAppResults(){const slot=document.getElementById('application-results');if(slot)slot.innerHTML=appListResults();}
function updateThreadResults(){const slot=document.getElementById('thread-results');if(slot)slot.innerHTML=messageThreadList();}
function setMessageDraft(value){const t=activeThread();if(!t)return;state.drafts[t.id]=value;const send=document.querySelector('[data-action="send-demo"]');if(send)send.disabled=!value.trim();}
function resetAll(){fixture=structuredClone(originalFixture);state={...state,applicationFilter:'All',applicationSort:'updated-desc',applicationSearch:'',documentApp:'all',documentCategory:'all',documentState:'all',messageApp:'all',messageSearch:'',drafts:{},simulatedReplies:{},selectedDocs:{},fileErrors:{},notificationOpen:false,mobileOpen:false,unreadNotifications:new Set(),unreadThreads:new Set()};bootState();render();notify('All demo-only changes have been reset.');}
function handleClick(event){const note=event.target.closest('[data-notification]');if(note){state.unreadNotifications.delete(note.dataset.notification);state.notificationOpen=false;return;}
const filter=event.target.closest('[data-filter-app]');if(filter){state.applicationFilter=filter.dataset.filterApp;render();return;}
const btn=event.target.closest('[data-action]');if(!btn)return;
const action=btn.dataset.action;
switch(action){
case 'open-menu':state.mobileOpen=true;render();break;
case 'close-menu':state.mobileOpen=false;render();break;
case 'toggle-notifications':state.notificationOpen=!state.notificationOpen;render();break;
case 'read-all':state.unreadNotifications.clear();render();notify('Demo alerts marked as read.');break;
case 'dismiss-toast':toastZone.innerHTML='';break;
case 'reset-doc-filters':resetDocs();break;
case 'choose-file':{if(event.target.closest('.file-input'))return;const id=btn.dataset.doc;const input=document.querySelector(`[data-file-input="${CSS.escape(id)}"]`);if(input){input.click();}break;}
case 'clear-file':delete state.selectedDocs[btn.dataset.doc];delete state.fileErrors[btn.dataset.doc];render();notify('Demo file selection cleared.');break;
case 'thread':state.activeThread=btn.dataset.id;state.unreadThreads.delete(btn.dataset.id);render();break;
case 'send-demo':{const t=activeThread();const draft=state.drafts[t?.id]?.trim();if(!t||!draft)return;state.simulatedReplies[t.id]??=[];state.simulatedReplies[t.id].push({id:`DEMO-UNSENT-${state.simulatedReplies[t.id].length+1}`,from:'Alex Morgan · Unsent demo reply',direction:'out',date:'2026-11-19',body:draft,unsent:true});state.drafts[t.id]='';render();notify('Demo only — no message sent.');break;}
case 'reset-demo':modal('Reset all demo changes?', 'This clears temporary demo file selections, draft and unsent messages, notification read states and preference edits. No live information is affected.', true);break;
case 'open-faq':{const faq=document.getElementById(btn.dataset.faq);if(faq){faq.open=true;faq.scrollIntoView({behavior:'smooth',block:'start'});}break;}
case 'demo-access':modal('This is a frontend demonstration','All names, funding requests, messages, documents and statuses are fictional. There is no authentication, secure upload or application backend, and no data is sent or stored beyond this browser session.');break;
}
}
function handleChange(event){const target=event.target;
if(target.matches('[data-file-input]')){const file=target.files?.[0];if(file)selectMetadata(target.dataset.fileInput,file);target.value='';return;}
if(target.matches('[data-field="app-sort"]')){state.applicationSort=target.value;updateAppResults();}
if(target.matches('[data-field="doc-app"]')){state.documentApp=target.value;if(location.hash.includes('?'))history.replaceState(null,'',location.pathname+location.search+'#/documents');render();}
if(target.matches('[data-field="doc-category"]')){state.documentCategory=target.value;render();}
if(target.matches('[data-field="doc-state"]')){state.documentState=target.value;render();}
if(target.matches('[data-field="message-app"]')){state.messageApp=target.value;if(location.hash.includes('?'))history.replaceState(null,'',location.pathname+location.search+'#/messages');state.activeThread=filteredThreads()[0]?.id||null;render();}
if(target.matches('[data-pref]'))state.profileDraft[target.dataset.pref]=target.checked;
}
function handleInput(event){const t=event.target;
if(t.matches('[data-field="app-search"]')){state.applicationSearch=t.value;updateAppResults();}
if(t.matches('[data-field="message-search"]')){state.messageSearch=t.value;if(!filteredThreads().some(x=>x.id===state.activeThread))state.activeThread=filteredThreads()[0]?.id||null;updateThreadResults();const c=document.getElementById('thread-content');if(c)c.innerHTML=threadContent();}
if(t.matches('[data-field="message-draft"]'))setMessageDraft(t.value);
if(t.closest('#profile-form')&&t.name)state.profileDraft[t.name]=t.value;
}
function handleSubmit(event){if(event.target.id!=='profile-form')return;event.preventDefault();const form=event.target;if(!form.reportValidity())return;
const validEmail=/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(state.profileDraft.email);
if(!validEmail){notify('Enter a valid fictional email address.','error');return;}
state.profile=structuredClone(state.profileDraft);render();notify('Demo profile and preferences updated in memory only.');}
function dragEvents(){root.addEventListener('dragover',e=>{const zone=e.target.closest('[data-drop-doc]');if(!zone)return;e.preventDefault();zone.classList.add('is-dragover');});root.addEventListener('dragleave',e=>{const zone=e.target.closest('[data-drop-doc]');if(zone)zone.classList.remove('is-dragover');});root.addEventListener('drop',e=>{const zone=e.target.closest('[data-drop-doc]');if(!zone)return;e.preventDefault();zone.classList.remove('is-dragover');const file=e.dataTransfer?.files?.[0];if(file)selectMetadata(zone.dataset.dropDoc,file);});}
function keyEvents(){root.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-drop-doc]')){e.preventDefault();e.target.querySelector('input[type="file"]')?.click();}if(e.key==='Escape'&&state.mobileOpen){state.mobileOpen=false;render();}if(e.key==='Escape'&&state.notificationOpen){state.notificationOpen=false;render();}});document.addEventListener('click',e=>{if(state.notificationOpen&&!e.target.closest('.notifications-wrap')&&!e.target.closest('[data-action="toggle-notifications"]')){state.notificationOpen=false;render();}});}
async function init(){root.addEventListener('click',handleClick);root.addEventListener('change',handleChange);root.addEventListener('input',handleInput);root.addEventListener('submit',handleSubmit);dragEvents();keyEvents();window.addEventListener('hashchange',navigate);
dialog.addEventListener('click',e=>{if(e.target.closest('[data-action="confirm-reset"]')){dialog.close();resetAll();}});try{const [demoRes,mapRes]=await Promise.all([fetch(new URL('../../data/demo.json',import.meta.url)),fetch(new URL('../../data/status-map.json',import.meta.url))]);if(!demoRes.ok||!mapRes.ok)throw new Error('Could not load local JSON fixtures');fixture=await demoRes.json();statusMap=await mapRes.json();validateFixture(fixture);originalFixture=structuredClone(fixture);bootState();render();}catch(err){console.error('Demo startup failure:',err);root.className='boot-screen';root.innerHTML=`<div class="boot-mark">GF<span>///</span></div><h1>Demo data unavailable.</h1><p>Open this folder through a local HTTP server, not via file://, and check that <code>data/demo.json</code> is present.</p><button class="btn btn-lime" id="retry-load">Retry loading ${icon('refresh',17)}</button><small class="mono">No live service was contacted.</small>`;document.getElementById('retry-load').addEventListener('click',()=>location.reload());}}
function validateFixture(d){const ids=new Set(d.applications.map(a=>a.id));if(ids.size!==3)throw new Error('Expected exactly 3 unique demo applications.');for(const collection of [d.documents,d.events,d.threads,d.notifications,d.history])for(const x of collection)if(!ids.has(x.applicationId))throw new Error(`Orphan fixture record ${x.id}`);for(const a of d.applications){if(!statusMap.statuses[a.status])throw new Error(`Unknown demo status: ${a.status}`);if(a.actionDocId&&!d.documents.some(v=>v.id===a.actionDocId&&v.applicationId===a.id))throw new Error(`Invalid action document for ${a.id}`);}}
init();
